/bin/bash -lc "jshell <<'EOF'
import java.time.*;
import java.time.format.*;
var f = DateTimeFormatter.ofPattern(\"uuuu-MM\").withResolverStyle(ResolverStyle.STRICT);
for (var s : new String[]{\"2026-09\", \"2026-13\", \"2026-00\", \"0000-01\"}) { try { System.out.println(s + \" -> \" + YearMonth.parse(s, f)); } catch (Exception e) { System.out.println(s + \" invalid\"); } }
EOF"
